using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver (resolves any type)
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — strongly-typed metadata access
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) TryGetTypeInfo<T>() — check-without-throwing
//    With the default resolver this will succeed for any type:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {info!.Type.Name}");
}

// Now demonstrate a case where TryGetTypeInfo returns false:
// Use a source-gen context that only knows about Person.
var restricted = new JsonSerializerOptions { TypeInfoResolver = SmallContext.Default };

if (restricted.TryGetTypeInfo<Person>(out _))
{
    Console.WriteLine("TryGetTypeInfo<Person> on restricted context → found");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person> on restricted context → NOT found");
}

if (restricted.TryGetTypeInfo<int>(out _))
{
    Console.WriteLine("TryGetTypeInfo<int> on restricted context → found");
}
else
{
    Console.WriteLine("TryGetTypeInfo<int> on restricted context → NOT found (no exception!)");
}

